/**
 * Contract test: the JSON produced by the real Swift `JSONEncoder` for
 * `HealthUploadRequest` (ios/FitCheckInSync/FitCheckInModels.swift) is accepted by the
 * server validator. Fixture generated by compiling the Swift models (see README).
 */
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import swiftRequest from '../fixtures/swift-upload-request.json'
import { METRICS, validateRequestEnvelope, validateSample, type HealthCategory } from '@shared/metrics/health-schema.ts'

describe('Swift → server wire contract', () => {
  it('envelope validates', () => {
    const r = validateRequestEnvelope(swiftRequest)
    expect(r.ok).toBe(true)
  })

  it('every Swift-encoded sample validates', () => {
    const env = validateRequestEnvelope(swiftRequest)
    if (!env.ok) throw new Error(env.error)
    const enabled = new Set<HealthCategory>(env.request.enabledCategories)
    const now = Date.parse('2026-11-08T03:00:00Z')
    for (const [i, s] of env.request.samples.entries()) {
      const r = validateSample(s, i, enabled, now)
      expect(r, JSON.stringify(s)).toMatchObject({ ok: true })
    }
  })

  it('Swift metric units match the server catalogue', () => {
    // Every FitCheckInMetric.unit in Swift must equal METRICS[metric].unit (parsed from the Swift source).
    const src = readFileSync(resolve(process.cwd(), '../ios/FitCheckInSync/FitCheckInModels.swift'), 'utf8')
    const metricEnum = src.slice(src.indexOf('enum FitCheckInMetric'), src.indexOf('var unit: String'))
    const raw = new Map<string, string>()
    for (const m of metricEnum.matchAll(/case (\w+)(?: = "([a-z_0-9]+)")?/g)) raw.set(m[1]!, m[2] ?? m[1]!)
    expect(raw.size).toBeGreaterThan(20)
    expect(new Set(raw.values())).toEqual(new Set(Object.keys(METRICS)))
  })

  it('Swift-encoded new metrics (vitals, mobility, body, running dynamics) validate', () => {
    const env = validateRequestEnvelope(swiftRequest)
    if (!env.ok) throw new Error(env.error)
    const types = env.request.samples.map((s) => (s as { metricType: string }).metricType)
    expect(types).toEqual(expect.arrayContaining(['oxygen_saturation', 'respiratory_rate', 'wrist_temperature', 'heart_rate_recovery', 'walking_steadiness', 'body_fat']))
    const run = env.request.samples.find((s) => (s as { metricType: string }).metricType === 'workout') as { metadata: Record<string, number> }
    expect(run.metadata.runningPowerW).toBe(262)
  })

  it('every category list matches the database enum (generated types)', async () => {
    const { Constants } = await import('@/lib/database.types')
    const dbEnum = [...Constants.public.Enums.health_category].sort()
    const { HEALTH_CATEGORIES } = await import('@shared/metrics/health-schema.ts')
    const { CATEGORIES } = await import('@/pages/shared/SharedPages')
    expect([...HEALTH_CATEGORIES].sort()).toEqual(dbEnum)
    expect([...CATEGORIES].sort()).toEqual(dbEnum)
    const swift = readFileSync(resolve(process.cwd(), '../ios/FitCheckInSync/FitCheckInModels.swift'), 'utf8')
    const block = swift.slice(swift.indexOf('enum FitCheckInCategory'), swift.indexOf('var id: String'))
    const swiftCats = [...block.matchAll(/case (\w+)(?: = "([a-z_0-9]+)")?/g)].map((m) => m[2] ?? m[1]!).sort()
    expect(swiftCats).toEqual(dbEnum)
  })
})
